-- Commands and Apps to be executed at launch (vendor defaults)
-- Generated by hyprlang2lua and reviewed for Hyprland 0.56.

local HOME = assert(os.getenv("HOME"), "HOME is not set")
local scriptsDir = HOME .. "/.config/hypr/scripts"
local UserScripts = HOME .. "/.config/hypr/UserScripts"
local lock = scriptsDir .. "/LockScreen.sh"
local SwwwRandom = UserScripts .. "/WallpaperAutoChange.sh"
local livewallpaper = "\"\""
local wallDIR = HOME .. "/Pictures/wallpapers" -- change path manually here if needed

--## wallpaper stuff ###
--exec-once = mpvpaper '*' -o "load-scripts=no no-audio --loop" $livewallpaper
-- wallpaper random
--exec-once = $SwwwRandom $wallDIR # random wallpaper switcher every 30 minutes

--## Startup ###
--exec-once = ags
--exec-once = blueman-applet
--exec-once = rog-control-center

-- Clipboard manager

-- Rainbow borders (disabled by default; use quick settings menu)
--exec-once = $UserScripts/RainbowBorders.sh

-- Here are list of features available but disabled by default
-- Persistent wallpaper
-- exec-once = awww-daemon && awww img $wallDIR/mecha-nostalgia.png

-- Gnome polkit for NixOS
--exec-once = $scriptsDir/Polkit-NixOS.sh

-- xdg-desktop-portal-hyprland (should be auto starting. However, you can force to start)
--exec-once = $scriptsDir/PortalHyprland.sh

hl.on("hyprland.start", function()
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd(HOME .. "/.config/hypr/scripts/Dropterminal.sh kitty &")
    hl.exec_cmd(scriptsDir .. "/Polkit.sh")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("nm-tray")
    hl.exec_cmd("swaync")
    hl.exec_cmd("waybar")
    hl.exec_cmd("qs -c overview")
    hl.exec_cmd(scriptsDir .. "/Hyprsunset.sh init")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("qs -c overview")
    hl.exec_cmd(scriptsDir .. "/KeybindsLayoutInit.sh")
end)
